29	#define LOOP_DEV   "/dev/uart1"
30	
31	/* 自包含内部回环：open → [波特率] → MCR.LOOP → write → read → 关 → close
32	 * 2026-08-27 v3：加可选波特率参数 argv[2]（如 "115200"/"1500000"），
33	 * 分别验证各档位下控制器+驱动是否全通——实证子 APP 波特率切换真生效。 */
34	static int loop_selftest(int baud)
35	{
36	  static const char msg[] = "UART1-LOOP-TEST-0123456789\r\n";
37	  char buf[64];
38	  int fd, mcr, n, total = 0;
39	
40	  fd = open(LOOP_DEV, O_RDWR | O_NONBLOCK);
41	  if (fd < 0)
42	    {
43	      printf("uartdbg_test: open %s failed errno=%d\n", LOOP_DEV, errno);
44	      return -1;
45	    }
46	
47	  /* 可选：设置波特率（不传则保持驱动当前值） */
48	  if (baud > 0)
49	    {
50	      struct termios tio;
51	      if (tcgetattr(fd, &tio) < 0 ||
52	          cfsetspeed(&tio, (speed_t)baud) < 0 ||
53	          tcsetattr(fd, TCSANOW, &tio) < 0)
54	        {
55	          printf("uartdbg_test: set baud %d failed errno=%d\n", baud, errno);
56	          close(fd);
57	          return -1;
58	        }
59	    }
60	
61	  /* 置 MCR.LOOP(bit4)：TX 数据芯片内部环回 RX，不经引脚 */
62	  mcr = 0x10;
63	  if (ioctl(fd, TIOCMSET, &mcr) < 0)
64	    {
65	      printf("uartdbg_test: TIOCMSET(LOOP) failed errno=%d\n", errno);
66	      close(fd);
67	      return -1;
68	    }
69	
70	  /* 发测试字节 */
71	  if (write(fd, msg, sizeof(msg) - 1) < 0)
72	    {
73	      printf("uartdbg_test: write failed errno=%d\n", errno);
74	      close(fd);
75	      return -1;
76	    }
77	
78	  /* 等数据环回 + 驱动接收 */
79	  usleep(300000);
80	
81	  /* 读回（非阻塞，尽量读完） */
82	  for (int i = 0; i < 10; i++)
83	    {
84	      n = read(fd, buf, sizeof(buf));
85	      if (n > 0)
86	        total += n;
87	      else
88	        break;
89	    }
90	
91	  /* 关内部回环 */
92	  mcr = 0;
93	  (void)ioctl(fd, TIOCMSET, &mcr);
94	  close(fd);
95	
96	  return total;
97	}
98	
99	int main(int argc, char *argv[])
100	{
101	  /* uartdbg_test loop [baud] —— 自包含内部回环（不依赖调试工具是否打开）
102	   * 可选波特率参数：uartdbg_test loop 115200 / uartdbg_test loop 1500000 */
103	  if (argc > 1 && strcmp(argv[1], "loop") == 0)
104	    {
105	      int baud = (argc > 2) ? atoi(argv[2]) : 0;
106	      int n = loop_selftest(baud);
107	      if (n > 0)
108	        {
109	          printf("uartdbg_test: LOOP OK — controller+driver 全通, rx=%d bytes\n", n);
110	          return 0;
111	        }
112	      printf("uartdbg_test: LOOP FAIL — rx=%d bytes\n", n);
113	      return -1;
114	    }
115	
116	  /* 默认：注入测试日志到 UI 窗口 */
117	  printf("uartdbg_test: injecting selftest log into UART debug tool...\n");
118	  if (dm_uart_dbg_inject_test() == 0)
119	    {
120	      printf("uartdbg_test: injected OK (see UART debug tool window)\n");
121	      return 0;
122	    }
123	
124	  printf("uartdbg_test: inject FAILED (inject buffer full?)\n");
125	  return -1;
126	}

