#include "ccu.h"
#include "ccu_frac.h"
#include "ccu_gate.h"
#include "ccu_nm.h"

struct _ccu_nm
{
    unsigned long   n, min_n, max_n;
    unsigned long   m, min_m, max_m;
};

static unsigned long ccu_nm_calc_rate(unsigned long parent,
                                      unsigned long n, unsigned long m)
{
    u64 rate = parent;

    rate *= n;
    rate /= m;

    return rate;
}

static void ccu_nm_find_best(unsigned long parent, unsigned long rate,
                             struct _ccu_nm *nm)
{
    unsigned long best_rate = 0;
    unsigned long best_n = 0, best_m = 0;
    unsigned long _n, _m;

    for (_n = nm->min_n; _n <= nm->max_n; _n++)
    {
        for (_m = nm->min_m; _m <= nm->max_m; _m++)
        {
            unsigned long tmp_rate = ccu_nm_calc_rate(parent,
                                     _n, _m);

            if (tmp_rate > rate)
            {
                continue;
            }

            if ((rate - tmp_rate) < (rate - best_rate))
            {
                best_rate = tmp_rate;
                best_n = _n;
                best_m = _m;
            }
        }
    }

    nm->n = best_n;
    nm->m = best_m;
}

static void ccu_nm_disable(struct clk_hw *hw)
{
    struct ccu_nm *nm = hw_to_ccu_nm(hw);

    return ccu_gate_helper_disable(&nm->common, nm->enable);
}

static int ccu_nm_enable(struct clk_hw *hw)
{
    struct ccu_nm *nm = hw_to_ccu_nm(hw);

    return ccu_gate_helper_enable(&nm->common, nm->enable);
}

static int ccu_nm_is_enabled(struct clk_hw *hw)
{
    struct ccu_nm *nm = hw_to_ccu_nm(hw);

    return ccu_gate_helper_is_enabled(&nm->common, nm->enable);
}

