/* 2026-08-27 P120 修复：1500000 档 rx=0。
 * 原 r528_uartdl 写死 R528_SCLK=24M，但 UART 总线时钟实际来自 apb1
 * （ccu-sun8iw20.c：bus_uart1_clk 父时钟 = apb1，0x524 MP_WITH_MUX，
 * mux 可选 dcxo24M/osc32k/psi-ahb/pll-periph0）。若 apb1 实际 ≠ 24M
 * （如 96M/100M），按 24M 算出的 dl 全错：1500000 档 dl=1 时实际
 * 波特率 = apb1/16 = 6M+，超出 RX 采样能力 → 回环 rx=0；
 * 而 115200 档 dl=13 误差小、回环自洽仍 LOOP OK——与实测完全吻合。
 * 修复：动态读取真实 apb1 时钟（读 CCU 0x524 解析 mux/M/P + 父时钟），
 * 替代写死假设。读不到时回退 24M（保持原行为）。 */
static uint32_t sunxi_pll_periph0_clk(void)
{
  /* pll-periph0-parent: 0x020, enable=bit27, n=bits[15:8] mult(+1,min12),
   * m=bits[1] div(+1). rate = 24M * n / m（ccu_nm_calc_rate） */
  uint32_t reg = hal_readl(R528_CCMU_VADDR + 0x020);
  uint32_t n, m;

  if (!(reg & (1u << 27)))
    {
      return 0; /* 未使能 */
    }

  n = ((reg >> 8) & 0xff) + 1;
  if (n < 12)
    {
      n = 12;
    }
  m = ((reg >> 1) & 0x1) + 1;

  return 24000000UL * n / m;
}

static uint32_t sunxi_psi_ahb_clk(void)
{
  /* psi-ahb: 0x510 MP_WITH_MUX, M=bits[1:0]+1, P=2^bits[9:8], mux=bits[25:24]
   * 父时钟: 0=dcxo24M 1=osc32k 2=iosc(~24M) 3=pll-periph0 */
  uint32_t reg = hal_readl(R528_CCMU_VADDR + 0x510);
  uint32_t mux = (reg >> 24) & 0x3;
  uint32_t m = ((reg >> 0) & 0x3) + 1;
  uint32_t p = 1u << ((reg >> 8) & 0x3);
  uint32_t parent = 24000000UL;

  if (mux == 3)
    {
      uint32_t pll = sunxi_pll_periph0_clk();
      if (pll > 0)
        {
          parent = pll;
        }
    }

  return parent / m / p;
}

static uint32_t sunxi_uart_sclk(void)
{
  /* apb1: 0x524 MP_WITH_MUX, M=bits[4:0]+1, P=2^bits[9:8], mux=bits[25:24]
   * 父时钟: 0=dcxo24M 1=osc32k 2=psi-ahb 3=pll-periph0 */
  uint32_t reg = hal_readl(R528_CCMU_VADDR + 0x524);
  uint32_t mux = (reg >> 24) & 0x3;
  uint32_t m = ((reg >> 0) & 0x1f) + 1;
  uint32_t p = 1u << ((reg >> 8) & 0x3);
  uint32_t parent = 24000000UL;

  if (mux == 2)
    {
      parent = sunxi_psi_ahb_clk();
    }
  else if (mux == 3)
    {
      uint32_t pll = sunxi_pll_periph0_clk();
      if (pll > 0)
        {
          parent = pll;
        }
    }

  return parent / m / p;
}

static inline uint32_t r528_uartdl(uint32_t baud)
{
  uint32_t sclk = sunxi_uart_sclk();

  if (sclk == 0)
    {
      sclk = R528_SCLK; /* 解析失败回退 24M */
    }

  return sclk / (baud << 4);
}

