/****************************************************************************
 * Public Functions
 ****************************************************************************/

int dm_uart_dbg_open(speed_t baud)
{
  struct termios tio;
  int fd;

  if (g_dbg_open)
    return 0;                        /* 已打开 */

  fd = open(DM_UART_DBG_DEV, O_RDWR | O_NONBLOCK);
  if (fd < 0)
    {
      LV_LOG_ERROR("[uart_dbg] open %s failed: %d", DM_UART_DBG_DEV, errno);
      return -1;
    }

  /* raw 模式 + 波特率 8N1 */
  memset(&tio, 0, sizeof(tio));
  if (tcgetattr(fd, &tio) < 0)
    {
      close(fd);
      return -1;
    }
  cfmakeraw(&tio);
  cfsetispeed(&tio, baud);
  cfsetospeed(&tio, baud);
  tio.c_cflag |= (CLOCAL | CREAD);
  if (tcsetattr(fd, TCSANOW, &tio) < 0)
    {
      close(fd);
      return -1;
    }

  g_dbg_fd = fd;
  g_dbg_ring_head = 0;
  g_dbg_ring_count = 0;
  g_dbg_total = 0;
  g_dbg_run = true;
  if (pthread_create(&g_dbg_thread, NULL, uart_dbg_reader,
                     (void *)(intptr_t)fd) != 0)
    {
      close(fd);
      g_dbg_fd = -1;
      g_dbg_run = false;
      return -1;
    }

  g_dbg_open = true;
  LV_LOG_USER("[uart_dbg] open %s ok", DM_UART_DBG_DEV);
  return 0;
}

int dm_uart_dbg_set_baud(speed_t baud)
{
  struct termios tio;

  if (!g_dbg_open || g_dbg_fd < 0)
    return -1;

  if (tcgetattr(g_dbg_fd, &tio) < 0)
    return -1;
  cfsetispeed(&tio, baud);
  cfsetospeed(&tio, baud);
  return tcsetattr(g_dbg_fd, TCSANOW, &tio);
}

void dm_uart_dbg_close(void)
{
  if (!g_dbg_open)
    return;

  g_dbg_run = false;
  pthread_join(g_dbg_thread, NULL);  /* 线程退出（≤200ms）后内部 close */

  g_dbg_open = false;
  g_dbg_fd = -1;

int hal_gpio_pinmux_set_function_early(unsigned long gpio_membase, gpio_pin_t pin, gpio_muxsel_t function_index)
{
	unsigned long config;
	uint32_t offset, shift, mask, reg;
	uint32_t arg;
	pin_config_param_t param;
	int ret = 0;

	config = GPIO_CFG_PACK(GPIO_TYPE_FUNC, function_index);
	param = pinconf_to_config_param(config);
	arg = pinconf_to_config_argument(config);

	ret = gpio_pconf_reg(pin, param, &offset, &shift, &mask);
	if (ret < 0)
	{
		return -1;
	}
	/* fix me: shuold we keep spin_lock to protect here?*/
	reg = hal_readl(gpio_membase + offset);
	reg &= ~(mask << shift);
	hal_writel(reg | arg << shift, gpio_membase + offset);

	if (ret < 0)
	{
		return ret;
	}
	return ret;
}

