/****************************************************************************
 * Name: arm_serialinit
 *
 * Description:
 *   Performs the low level UART initialization early in debug so that the
 *   serial console will be available during bootup.  This must be called
 *   before arm_serialinit.
 *
 *   NOTE: Configuration of the CONSOLE UART was performed by up_lowsetup()
 *   very early in the boot sequence.
 *
 ****************************************************************************/

void up_earlyserialinit(void)
{
  /* Configure all UARTs (except the CONSOLE UART) and disable interrupts */
#if defined(CONFIG_R528_UART0)
  r528_uart0config();
#endif

#if defined(CONFIG_R528_UART1)
  r528_uart1config();
#endif

#if defined(CONFIG_R528_UART2)
  r528_uart2config();
#endif

#if defined(CONFIG_R528_UART3)
  r528_uart3config();
#endif

#ifdef CONSOLE_DEV
  CONSOLE_DEV.isconsole = true;
  up_setup(&CONSOLE_DEV);
#endif
}

/****************************************************************************
 * Name: arm_serialinit
 *
 * Description:
 *   Register serial console and serial ports.  This assumes that
 *   up_earlyserialinit was called previously.
 *
 ****************************************************************************/

void arm_serialinit(void)
{
  up_earlyserialinit();

#ifdef CONSOLE_DEV
  (void)uart_register("/dev/console", &CONSOLE_DEV);
#endif

#if defined(CONFIG_R528_UART0)
  (void)uart_register("/dev/uart0", &g_uart0port);
#endif
#if defined(CONFIG_R528_UART1)
  (void)uart_register("/dev/uart1", &g_uart1port);
#endif
#if defined(CONFIG_R528_UART2)
  (void)uart_register("/dev/uart2", &g_uart2port);
#endif
#if defined(CONFIG_R528_UART3)
  (void)uart_register("/dev/uart3", &g_uart3port);
#endif
}

/****************************************************************************
 * Name: up_putc
 *
 * Description:
 *   Provide priority, low-level access to support OS debug  writes
 *
 ****************************************************************************/

void up_putc(int ch)
{
#ifdef HAVE_SERIAL_CONSOLE
  irqstate_t flags;
  flags = enter_critical_section();
  struct up_dev_s *priv = (struct up_dev_s *)CONSOLE_DEV.priv;
  uint32_t ier;
  up_disableuartint(priv, &ier);
#endif

  /* Check for LF */

  if (ch == '\n')
    {
      /* Add CR */

      arm_lowputc('\r');
    }

  arm_lowputc(ch);
#ifdef HAVE_SERIAL_CONSOLE
  up_restoreuartint(priv, ier);
  leave_critical_section(flags);

